<template><view class="page"><view v-if="error" class="card"><view class="error">{{error}}</view><button class="secondary" @click="load">重新加载</button></view><view v-else-if="loading" class="loading">正在加载…</view><EmptyState v-else-if="!plan"/><template v-else><view class="card exam-card"><view class="row"><view class="row"><view class="exam-icon">🎓</view><view><picker :range="plans" range-key="examName" @change="change"><view class="exam-name">{{plan.examName}} ⌄</view></picker><view class="muted">{{plan.examDate}}</view></view></view><view class="count"><view class="muted">距离考试</view><text>{{plan.remainingDays}}</text><text class="unit">天</text></view></view><view class="actions"><view @click="info"><view class="action-icon blue">ⓘ</view><text>考试信息</text></view><view @click="showStages=!showStages"><view class="action-icon mint">⚙</view><text>阶段路线</text></view><view @click="create"><view class="action-icon coral">＋</view><text>新建考试</text></view></view></view><view class="row section"><text>学习计划</text><button class="small primary" @click="create">＋ 添加计划</button></view><view v-for="(s,i) in subjects" :key="s.name" class="card subject-card" @click="tasks(s.name)"><view :class="['subject-icon','color-'+(i%3)]">{{s.name.slice(0,1)}}</view><view class="subject-detail"><view class="row"><text class="subject-name">{{s.name}}</text><text class="percent">{{s.progress}}%</text></view><view class="progress"><view class="fill" :style="{width:s.progress+'%'}"/></view><view class="muted">{{s.minutes}}分钟已完成 · 每日{{s.daily}}分钟</view></view><text class="arrow">›</text></view><view v-if="showStages"><view class="section">阶段路线</view><view v-for="s in plan.stages" :key="s.id" class="card"><view class="row"><text class="subject-name">{{s.name}}</text><text class="badge">{{s.progress}}%</text></view><view class="muted range">{{s.startDate}} — {{s.endDate}}</view><view>{{s.goal}}</view></view></view><view class="card note"><view class="row"><text>今日任务与学习预算</text><text class="link" @click="tasks()">查看 ›</text></view><view class="muted">每天安排 {{plan.dailyMinutes}} 分钟，按科目权重分配。</view></view></template></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api,selected,select} from '../../api';import {daysBetween} from '../../utils/planner.mjs';import EmptyState from '../../components/EmptyState.vue'
const plans=ref([]),plan=ref(null),data=ref(null),firstTasks=ref([]),error=ref(''),loading=ref(true),showStages=ref(false)
const subjects=computed(()=>plan.value?plan.value.subjects.map(s=>{const daily=firstTasks.value.find(t=>t.subject===s.name)?.duration||0,minutes=data.value?.subjects.find(t=>t.name===s.name)?.minutes||0,total=daily*daysBetween(plan.value.startDate,plan.value.examDate);return {...s,daily,minutes,progress:total?Math.min(100,Math.round(minutes/total*100)):0}}):[])
async function load(){loading.value=true;error.value='';try{plans.value=await api.plans();const p=plans.value.find(p=>p.id===selected())||plans.value[0];plan.value=p?await api.plan(p.id):null;if(p){select(p.id);[data.value,firstTasks.value]=await Promise.all([api.records(p.id),api.tasks(p.id,plan.value.startDate)])}}catch(e){error.value=e.message}finally{loading.value=false}}
async function change(e){select(plans.value[Number(e.detail.value)].id);await load()}onShow(load)
function create(){uni.navigateTo({url:'/pages/exam/create'})}function tasks(subject=''){uni.setStorageSync('dkm-task-subject',typeof subject==='string'?subject:'');uni.switchTab({url:'/pages/task/index'})}function info(){uni.showModal({title:'考试信息',content:plan.value.examName+'\n考试日期：'+plan.value.examDate+'\n每日学习：'+plan.value.dailyMinutes+'分钟\n基础：'+({weak:'薄弱',normal:'一般',good:'较好'}[plan.value.level]),showCancel:false})}
</script>
<style scoped>.exam-card{margin-top:8rpx}.exam-icon{width:82rpx;height:82rpx;background:#ECF4FA;border-radius:20rpx;font-size:48rpx;text-align:center;line-height:82rpx}.exam-name{font-size:31rpx;font-weight:750;max-width:330rpx}.exam-card .muted{font-size:22rpx}.count{text-align:right;flex-shrink:0}.count>text{font-size:46rpx;font-weight:850;line-height:1.3}.count .unit{font-size:25rpx;margin-left:4rpx}.actions{display:flex;justify-content:space-around;padding-top:26rpx;text-align:center;color:#879991;font-size:22rpx}.action-icon{font-size:37rpx;width:60rpx;height:60rpx;border-radius:18rpx;line-height:60rpx;margin:0 auto 6rpx}.blue{color:#588FFF;background:#EDF2FF}.mint{color:#16A588;background:#E7F7F1}.coral{color:#FF7079;background:#FFF0F0}.small{padding:8rpx 20rpx;font-size:24rpx;font-weight:500}.subject-card{display:flex;align-items:center;gap:20rpx;padding:25rpx 24rpx}.subject-icon{width:82rpx;height:82rpx;flex-shrink:0;border-radius:22rpx;line-height:82rpx;text-align:center;color:white;font-size:37rpx;font-weight:800}.color-0{background:linear-gradient(135deg,#FFA4AB,#FF5F73)}.color-1{background:linear-gradient(135deg,#8BBAFF,#5967F7)}.color-2{background:linear-gradient(135deg,#FFCE80,#FFA52F)}.subject-detail{flex:1;min-width:0}.subject-name{font-size:29rpx;font-weight:700}.percent{font-size:25rpx}.subject-detail .progress{margin-top:10rpx;height:12rpx}.subject-detail .muted{font-size:20rpx;margin-top:6rpx}.arrow{color:#93AAA0;font-size:38rpx}.range{margin:18rpx 0 10rpx}.note{margin-top:28rpx}.note .muted{font-size:22rpx;margin-top:12rpx}</style>
